import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"The OTA / A-B service from the app side","description":"","frontmatter":{},"headers":[],"relativePath":"l1/ota.md","filePath":"l1/ota.md"}'),n={name:"l1/ota.md"};function d(c,e,i,r,p,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-ota-a-b-service-from-the-app-side" tabindex="-1">The OTA / A-B service from the app side <a class="header-anchor" href="#the-ota-a-b-service-from-the-app-side" aria-label="Permalink to &quot;The OTA / A-B service from the app side&quot;">​</a></h1><p>The update machinery lives in the selfhost service (<code>ocos/services/selfhost/</code>); apps reach it through the L1SVC &quot;ota&quot; category and the config store.</p><h2 id="the-l1svc-surface" tabindex="-1">The L1SVC surface <a class="header-anchor" href="#the-l1svc-surface" aria-label="Permalink to &quot;The L1SVC surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Op</th><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td>1</td><td><code>checkupdate</code></td><td>fetch + parse the manifest, compare (numeric build compare, BUG-0347)</td></tr><tr><td>2</td><td><code>config</code></td><td>list / get / set / restore / path - the /etc/opencube.conf store</td></tr><tr><td>5</td><td><code>update</code></td><td><code>status</code> / <code>--local &lt;pkg&gt;</code> / bare = the online chain</td></tr><tr><td>6</td><td><code>rollback</code></td><td>flip the boot flag to the other slot</td></tr><tr><td>7-16</td><td><code>update_pkg_test</code> .. <code>real_update_test</code></td><td>the in-guest test battery</td></tr></tbody></table><p><code>update status</code> prints the machine picture the wizards probe:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update: current version: 3.0.0-...</span></span>
<span class="line"><span>update: current boot: ISO          (or slot A / slot B)</span></span>
<span class="line"><span>update: next boot: (default)</span></span>
<span class="line"><span>update: available: none (up to date)</span></span>
<span class="line"><span>update: online update: enabled</span></span>
<span class="line"><span>update: A/B disk: present          &lt;- the wizard anchor</span></span></code></pre></div><h2 id="the-chain-what-the-online-flow-does" tabindex="-1">The chain (what the online flow does) <a class="header-anchor" href="#the-chain-what-the-online-flow-does" aria-label="Permalink to &quot;The chain (what the online flow does)&quot;">​</a></h2><p>check (manifest from the configured <code>update_url</code>) -&gt; download -&gt; verify (manifest SHA256 enforced inside install) -&gt; install onto the <em>inactive</em> slot -&gt; set boot -&gt; &quot;reboot required&quot;.</p><p>Offline: <code>update --local /path/to/package.tar.gz</code> runs the same install path from an attached volume.</p><h2 id="the-a-b-disk" tabindex="-1">The A/B disk <a class="header-anchor" href="#the-a-b-disk" aria-label="Permalink to &quot;The A/B disk&quot;">​</a></h2><p>Two slots + boot flag, created by <code>abdisk &lt;dev&gt;</code> (or the <code>disk-tool</code> A/B manager wizard). GRUB reads the flag; the menu offers force-slot entries. <code>abcfg</code> shows the exact grub.cfg those commands write. The install target is the inactive slot (BUG-0110: <code>update_target_slot()</code> decides, not the caller).</p><h2 id="the-config-keys-etc-opencube-conf" tabindex="-1">The config keys (/etc/opencube.conf) <a class="header-anchor" href="#the-config-keys-etc-opencube-conf" aria-label="Permalink to &quot;The config keys (/etc/opencube.conf)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update_url=https://cubestudio-dev.github.io/OpenCubeOS/update.json</span></span>
<span class="line"><span>package_url=https://github.com/cubestudio-dev/OpenCubeOS/releases/latest</span></span>
<span class="line"><span>auto_check=no</span></span>
<span class="line"><span>online_update=yes</span></span>
<span class="line"><span>shell.lang=en</span></span></code></pre></div><p><code>config get update_url</code> is what the update wizard&#39;s DNS step parses (scheme -&gt; host) before resolving it.</p><h2 id="the-mega-app" tabindex="-1">The mega-app <a class="header-anchor" href="#the-mega-app" aria-label="Permalink to &quot;The mega-app&quot;">​</a></h2><p><code>update</code> (no args) = the 5-step wizard; every other argument shape is the verbatim op. See the user manual&#39;s <a href="./../manual/update-ota.html">../manual/update-ota.md</a> for the operator view and <a href="./wizard-library.html">wizard-library.md</a> for the anchor discipline.</p><h2 id="in-guest-tests" tabindex="-1">In-guest tests <a class="header-anchor" href="#in-guest-tests" aria-label="Permalink to &quot;In-guest tests&quot;">​</a></h2><p><code>ab_partition_test</code>, the <code>update_*_test</code> battery, <code>checkupdate_test</code>, <code>config_test</code> - all classic ops of the sysdiag/ update tables, all in the registry.</p>`,18)])])}const f=t(n,[["render",d]]);export{u as __pageData,f as default};
